from typing import Dict, List, Optional


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: Dict[str, bool] = {}
        self._next_id: int = 1
        self._tickets: Dict[int, dict] = {}
        # Queues per priority (list of ticket ids, FIFO order)
        self._queues: Dict[str, List[int]] = {p: [] for p in self.PRIORITIES}

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title must not be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority!r}")
        if customer not in self._customers:
            raise ValueError(f"Unknown customer: {customer!r}")

        ticket_id = self._next_id
        self._next_id += 1

        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",  # open | closed
        }
        self._queues[priority].append(ticket_id)
        return ticket_id

    def next_ticket(self) -> Optional[int]:
        # Process priorities from highest (last in tuple) to lowest.
        for priority in reversed(self.PRIORITIES):
            queue = self._queues[priority]
            while queue:
                ticket_id = queue.pop(0)
                ticket = self._tickets.get(ticket_id)
                if ticket is not None and ticket["status"] == "open":
                    ticket["status"] = "in_progress"
                    return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        ticket = self._tickets.get(ticket_id)
        if ticket is None:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        ticket["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        ticket = self._tickets.get(ticket_id)
        if ticket is None:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        if ticket["status"] == "closed":
            raise ValueError(f"Cannot reopen closed ticket {ticket_id}.")
        if ticket["status"] == "open":
            # Already in the queue; re-adding would duplicate it.
            return
        ticket["status"] = "open"
        self._queues[ticket["priority"]].append(ticket_id)
